-- Additive upgrade for backlog issues #8-12. Select the target database first.
-- Existing business data is not replaced. MySQL 8.0.16+ / utf8mb4.
CREATE TABLE IF NOT EXISTS `campaign_windows` (Id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, CampaignId BIGINT UNSIGNED NOT NULL, Stage VARCHAR(30) NOT NULL, OpensAt DATETIME(6) NOT NULL, ClosesAt DATETIME(6) NOT NULL, UNIQUE KEY uq_window (CampaignId,Stage), FOREIGN KEY(CampaignId) REFERENCES campaigns(id), CHECK(ClosesAt>=OpensAt)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `campaign_eligibility_policies` (Id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, CampaignId BIGINT UNSIGNED NOT NULL UNIQUE, MinimumGpa4 DECIMAL(4,2) NULL, MinimumGpa10 DECIMAL(4,2) NULL, MinimumCredits INT UNSIGNED NULL, PrerequisiteNote LONGTEXT NULL, FOREIGN KEY(CampaignId) REFERENCES campaigns(id), CHECK(MinimumGpa4 BETWEEN 0 AND 4), CHECK(MinimumGpa10 BETWEEN 0 AND 10)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `campaign_exceptions` (Id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, CampaignId BIGINT UNSIGNED NOT NULL, UserId VARCHAR(255) NOT NULL, Stage VARCHAR(30) NOT NULL, ExpiresAt DATETIME(6) NOT NULL, Reason VARCHAR(1000) NOT NULL, ApprovedBy VARCHAR(255) NOT NULL, FOREIGN KEY(CampaignId) REFERENCES campaigns(id), FOREIGN KEY(UserId) REFERENCES AspNetUsers(Id), FOREIGN KEY(ApprovedBy) REFERENCES AspNetUsers(Id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `student_eligibility_evidence` (Id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, CampaignId BIGINT UNSIGNED NOT NULL, StudentProfileId BIGINT UNSIGNED NOT NULL, Credits INT UNSIGNED NOT NULL, PrerequisitesMet TINYINT(1) NOT NULL, SourceNote VARCHAR(1000) NOT NULL, RecordedBy VARCHAR(255) NOT NULL, RecordedAt DATETIME(6) NOT NULL, UNIQUE KEY uq_evidence(CampaignId,StudentProfileId), FOREIGN KEY(CampaignId) REFERENCES campaigns(id), FOREIGN KEY(StudentProfileId) REFERENCES student_profiles(id), FOREIGN KEY(RecordedBy) REFERENCES AspNetUsers(Id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `companies` (Id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, OwnerUserId VARCHAR(255) NOT NULL, MajorId BIGINT UNSIGNED NOT NULL, Name VARCHAR(200) NOT NULL, RegistrationCode VARCHAR(60) NOT NULL UNIQUE, Email VARCHAR(256) NOT NULL, ContactName VARCHAR(180) NOT NULL, Address VARCHAR(255) NOT NULL, Status VARCHAR(20) NOT NULL, ReviewReason VARCHAR(1000) NULL, ReviewedBy VARCHAR(255) NULL, ReviewedAt DATETIME(6) NULL, FOREIGN KEY(OwnerUserId) REFERENCES AspNetUsers(Id), FOREIGN KEY(MajorId) REFERENCES majors(id), FOREIGN KEY(ReviewedBy) REFERENCES AspNetUsers(Id), CHECK(Status IN ('PENDING','APPROVED','REJECTED'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `company_mentors` (Id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, CompanyId BIGINT UNSIGNED NOT NULL, UserId VARCHAR(255) NOT NULL, Name VARCHAR(180) NOT NULL, UNIQUE KEY uq_mentor(CompanyId,UserId), FOREIGN KEY(CompanyId) REFERENCES companies(Id), FOREIGN KEY(UserId) REFERENCES AspNetUsers(Id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `student_assignments` (Id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, CampaignId BIGINT UNSIGNED NOT NULL, StudentProfileId BIGINT UNSIGNED NOT NULL, LecturerProfileId BIGINT UNSIGNED NOT NULL, CompanyMentorId BIGINT UNSIGNED NULL, QuotaOverrideReason VARCHAR(1000) NULL, AssignedBy VARCHAR(255) NOT NULL, AssignedAt DATETIME(6) NOT NULL, UNIQUE KEY uq_assignment(CampaignId,StudentProfileId), FOREIGN KEY(CampaignId) REFERENCES campaigns(id), FOREIGN KEY(StudentProfileId) REFERENCES student_profiles(id), FOREIGN KEY(LecturerProfileId) REFERENCES lecturer_profiles(id), FOREIGN KEY(CompanyMentorId) REFERENCES company_mentors(Id), FOREIGN KEY(AssignedBy) REFERENCES AspNetUsers(Id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

